use chaoscontrol_explore::explorer::journal::{decode_segment, segment_file_name, SegmentDigest};
use chaoscontrol_explore::snapshot_store::{FileSnapshotStore, SnapshotStore};
use serde_json::{json, Value};
use std::error::Error;
use std::path::Path;
use std::time::Instant;

fn main() -> Result<(), Box<dyn Error>> {
    let args: Vec<String> = std::env::args().collect();
    match args.get(1).map(String::as_str) {
        Some("journal") if args.len() == 4 => {
            let last: u64 = args[3].parse()?;
            let mut previous = SegmentDigest::ZERO;
            let mut rows = Vec::new();
            for seq in 0..=last {
                let path = Path::new(&args[2]).join(segment_file_name(seq));
                let started = Instant::now();
                let bytes = std::fs::read(&path)?;
                let read_seconds = started.elapsed().as_secs_f64();
                let started = Instant::now();
                let segment = decode_segment(&bytes)?;
                let decode_seconds = started.elapsed().as_secs_f64();
                if segment.header().seq != seq || segment.header().previous_digest != previous {
                    return Err("segment sequence or digest chain mismatch".into());
                }
                previous = segment.digest();
                rows.push(json!({
                    "seq": seq, "bytes": bytes.len(), "records": segment.records().len(),
                    "read_seconds": read_seconds, "decode_seconds": decode_seconds,
                    "record_kinds": segment.records().iter().map(|r| r.kind().get()).collect::<Vec<_>>()
                }));
            }
            println!("{}", json!({"mode":"journal-envelope-decoding-only","segments":rows,
                "non_claim":"Validates bounded segment envelopes and their digest chain, not Campaign record semantics or whole-history validation."}));
        }
        Some("snapshot") if args.len() == 5 => {
            let bug: Value = serde_json::from_slice(&std::fs::read(&args[3])?)?;
            let reference = serde_json::from_value(bug["replay_parent_snapshot_ref"].clone())?;
            let store = FileSnapshotStore::new(&args[2]);
            let started = Instant::now();
            let artifact = store.get_snapshot_artifact(&reference)?;
            let get_seconds = started.elapsed().as_secs_f64();
            let output_store = FileSnapshotStore::new(&args[4]);
            let mut puts = Vec::new();
            for invocation in 1..=2 {
                let started = Instant::now();
                let written = output_store.put_snapshot(&artifact.snapshot, artifact.replay_parent_depth)?;
                let put_seconds = started.elapsed().as_secs_f64();
                let same_reference = written == reference;
                if !same_reference { return Err("offline recode changed snapshot reference".into()); }
                puts.push(json!({"invocation":invocation,"put_seconds":put_seconds,
                    "reference_unchanged":same_reference,
                    "compressed_bytes":std::fs::metadata(Path::new(&args[4]).join(&written.path))?.len()}));
            }
            println!("{}", json!({"mode":"offline-snapshot-store-consumer","get_seconds":get_seconds,
                "parent_depth":artifact.replay_parent_depth,"tick":artifact.tick,"vm_count":artifact.vm_count,
                "reference":reference,"puts":puts,
                "non_claim":"Only local retained-data store get/put cost; no KVM, VM restore, new campaign, or release verdict."}));
        }
        _ => return Err("usage: probe journal <epoch-dir> <last-segment> | snapshot <artifact-root> <bug-json> <new-output-root>".into()),
    }
    Ok(())
}

use campaign_core::{apply_control_event, reconstruct, CampaignControlEvent, FrontierState};
use chaoscontrol_explore::campaign_adapter::decode_control_event;
use chaoscontrol_explore::explorer::journal::{decode_segment, segment_file_name, SegmentDigest};
use serde_json::json;
use std::error::Error;
use std::path::Path;
use std::time::Instant;

type Result<T, E = Box<dyn Error>> = std::result::Result<T, E>;

fn apply(mut state: FrontierState, events: &[CampaignControlEvent]) -> Result<FrontierState> {
    for event in events {
        state = apply_control_event(state, event).map_err(|error| format!("control apply: {error:?}"))?;
    }
    Ok(state)
}

fn main() -> Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        return Err("usage: core-probe <epoch-directory> <settlement-segment>".into());
    }
    let target: u64 = args[2].parse()?;
    if target == 0 || target % 2 != 0 {
        return Err("select a nonzero even settlement segment".into());
    }
    let mut before = Vec::new();
    let mut settlement = Vec::new();
    let mut previous = SegmentDigest::ZERO;
    let started = Instant::now();
    for seq in 0..=target {
        let bytes = std::fs::read(Path::new(&args[1]).join(segment_file_name(seq)))?;
        let segment = decode_segment(&bytes)?;
        if segment.header().seq != seq || segment.header().previous_digest != previous {
            return Err("segment sequence or digest chain mismatch".into());
        }
        previous = segment.digest();
        for record in segment.records() {
            if record.kind().get() == 3 {
                let event = decode_control_event(record.payload())
                    .map_err(|error| format!("control decode: {error:?}"))?;
                if seq == target { settlement.push(event); } else { before.push(event); }
            }
        }
    }
    let load_seconds = started.elapsed().as_secs_f64();
    let started = Instant::now();
    let base = reconstruct(&before).map_err(|error| format!("prefix reconstruct: {error:?}"))?;
    let prefix_seconds = started.elapsed().as_secs_f64();
    let started = Instant::now();
    let expected = apply(base.clone(), &settlement)?;
    let one_pass_seconds = started.elapsed().as_secs_f64();
    println!("{}", json!({"phase":"prefix-and-one-pass-complete","target_segment":target,
        "prefix_controls":before.len(),"settlement_controls":settlement.len(),
        "load_seconds":load_seconds,"prefix_seconds":prefix_seconds,"one_pass_seconds":one_pass_seconds}));
    let started = Instant::now();
    let mut applications: usize = 0;
    for cutoff in 0..settlement.len() {
        let current = apply(base.clone(), &settlement[..cutoff])?;
        applications += cutoff;
        if Some(current.state_id) != settlement[cutoff].state_before_id() {
            return Err("replayed suffix did not reach recorded next-event state".into());
        }
    }
    let sealed = apply(base.clone(), &settlement)?;
    applications += settlement.len();
    let held_projection_suffix_seconds = started.elapsed().as_secs_f64();
    if sealed != expected {
        return Err("single pass and held-projection suffix replay changed state".into());
    }
    let k = settlement.len();
    if applications != k * (k - 1) / 2 + k {
        return Err("suffix application count mismatch".into());
    }
    println!("{}", json!({"schema":"chaoscontrol.offline-campaign-core-suffix-observation.v1",
        "target_segment":target,"prefix_controls":before.len(),"prefix_candidates":base.candidates.len(),
        "settlement_controls":k,"one_pass_applications":k,"suffix_applications":applications,
        "one_pass_seconds":one_pass_seconds,"held_projection_suffix_seconds":held_projection_suffix_seconds,
        "all_recorded_state_boundaries_match":true,"final_complete_state_equal":true,
        "final_state_digest":sealed.state_id.digest,
        "non_claim":"Measures the core suffix-replay subpath using actual retained control events. Does not run Choregraph publication planning, graph scans/clones, fsync, KVM, a campaign, or a release gate. One-pass comparison is diagnostic only; no production validation was removed or bypassed."}));
    Ok(())
}
